import{K as a,a as c,c as s,b as o,k as h,q as t,ac as l}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Office 综合实战：从数据到报告、演示和会议","description":"用一个月报项目串联 Excel、Word、PowerPoint、Outlook 与 OneNote，定义数据来源、更新顺序、版本命名、审阅和交付验收。","frontmatter":{"title":"Office 综合实战：从数据到报告、演示和会议","description":"用一个月报项目串联 Excel、Word、PowerPoint、Outlook 与 OneNote，定义数据来源、更新顺序、版本命名、审阅和交付验收。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"实践案例","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · 协作、实战与排错","summary":"用一个月报项目串联 Excel、Word、PowerPoint、Outlook 与 OneNote，定义数据来源、更新顺序、版本命名、审阅和交付验收。","status":"active","related":[{"title":"Access 查询、窗体、报表与维护","link":"/tools/office/access/forms","kind":"使用指南","scope":"general","audience":"general"},{"title":"Access 入门、表设计与数据关系","link":"/tools/office/access/data","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 查找匹配：XLOOKUP、VLOOKUP 与 INDEX MATCH","link":"/tools/office/excel/lookup","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 打印、导出与工作簿交付","link":"/tools/office/excel/printing","kind":"使用指南","scope":"general","audience":"general"},{"title":"Excel 公式、相对引用与绝对引用","link":"/tools/office/excel/formulas","kind":"使用指南","scope":"general","audience":"general"}],"prev":{"text":"Office 云端共享、共同编辑与版本管理","link":"/tools/office/collaboration/sharing"},"next":{"text":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Office 云端共享、共同编辑与版本管理","link":"/tools/office/collaboration/sharing"},"next":{"text":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting"}},"headers":[],"relativePath":"tools/office/collaboration/workflow.md","filePath":"tools/office/collaboration/workflow.md"}'),d={name:"tools/office/collaboration/workflow.md"},k=Object.assign(d,{setup(f){const i={path:"/tools/office/collaboration/workflow",app:"Excel",title:"让表格、报告和演示使用同一组数字",steps:[{tab:"数据",command:"全部刷新",setting:"先查询后透视表；核对十月金额 3160",anchor:"walkthrough-1"},{tab:"开始",command:"复制",setting:"复制核对后的汇总；保留来源与单位",anchor:"walkthrough-2"},{tab:"文件",command:"导出",setting:"三份材料同一截止时间；重新打开核对",anchor:"walkthrough-3",app:"Word / PowerPoint"}]};return(u,e)=>{const r=a("OfficeGuide"),n=a("Mermaid");return c(),s("div",null,[e[0]||(e[0]=o("h1",{id:"office-综合实战-从数据到报告、演示和会议",tabindex:"-1"},[h("Office 综合实战：从数据到报告、演示和会议 "),o("a",{class:"header-anchor",href:"#office-综合实战-从数据到报告、演示和会议","aria-label":'Permalink to "Office 综合实战：从数据到报告、演示和会议"'},"​")],-1)),e[1]||(e[1]=o("p",null,"本篇把各软件的单项技能串成一个完整工作流。目标是数字能追溯、内容能更新、文件版本一致，而不是让每个软件都保存一套互不关联的数据。",-1)),t(r,{guide:i}),e[2]||(e[2]=l('<h2 id="source" tabindex="-1">确定唯一数据源 <a class="header-anchor" href="#source" aria-label="Permalink to &quot;确定唯一数据源 {#source}&quot;">​</a></h2><p>采用<a href="/tools/office/excel/project">Excel 月报案例</a>，统计 2026 年 10 月已完成订单，金额 3160，订单数 5，部门金额运营 2440、技术 720。所有材料引用这组口径；原始八条全部订单金额 5120 不能混写成月度完成金额。</p><p>明确谁负责更新数据、谁确认口径、谁审批结论。工作目录可分为“原始数据、工作文件、交付版本”，不要让输出 PDF、历史备份和源数据混在 Power Query 正在读取的同一个目录中。</p><h2 id="sequence" tabindex="-1">按依赖顺序更新 <a class="header-anchor" href="#sequence" aria-label="Permalink to &quot;按依赖顺序更新 {#sequence}&quot;">​</a></h2>',4)),t(n,{source:""}),e[3]||(e[3]=l('<ol><li>更新 Excel 数据，先检查异常记录，再刷新查询和透视表。</li><li>用独立汇总方式核对总额和行数，记录统计范围及截止时间。</li><li>更新 Word 中的结果、表格、风险和建议，刷新题注、目录与引用。</li><li>更新 PowerPoint 图表和结论，确认静态图片已重新生成，链接图表已实际更新。</li><li>审阅人核对一致性，处理批注与修订，确认版本。</li><li>导出 PDF，检查成品，再组织会议和交付。</li></ol><p>刷新 Excel 后不会自动让所有截图、文字中的数字和邮件正文同步改变。建立一个“关键指标检查表”，列出它们在各文件中的位置，是很实用的防遗漏方式。</p><h2 id="roles" tabindex="-1">三类材料各自承担什么 <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;三类材料各自承担什么 {#roles}&quot;">​</a></h2><p>Excel 保留可计算的明细、公式和汇总；Word 解释背景、口径、限制和完整建议；PowerPoint 展示核心结论和需要讨论的决定。不要为了三份材料完全一致而复制相同篇幅，应让数值与定义一致，表达深度适合各自用途。</p><p>例如 Word 详细解释取消订单为什么排除，PPT 只在图表旁标注“仅已完成”，Excel 保留状态字段和筛选公式。三者应相互支持，且能从结论回到数据。</p><h2 id="meeting" tabindex="-1">会议前后 <a class="header-anchor" href="#meeting" aria-label="Permalink to &quot;会议前后 {#meeting}&quot;">​</a></h2><p>通过 Outlook 安排会议时写明目标、议程、材料链接和需要提前完成的阅读。链接权限应匹配参与者；本教程不会代替你发送邀请。会议中用 OneNote 记录决定、未决问题、负责人和期限，避免只留下讨论流水账。</p><p>会后按决定更新行动清单，修改关键指标时重新走核对和定稿流程。会议记录中的旧数字应保留其时间背景，不能无说明地覆盖成后来的结果。</p><h2 id="practice" tabindex="-1">版本和验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;版本和验收 {#practice}&quot;">​</a></h2><p>交付文件使用同一版本标识，例如 <code>月报_2026-10_v1.0.xlsx</code>、<code>报告_2026-10_v1.0.pdf</code>、<code>汇报_2026-10_v1.0.pptx</code>。配一段说明：统计口径、数据截止日期、源文件位置、是否可刷新以及已知限制。</p><p>做一次变更演练：在副本把 O004 数量由 5 改为 6，预期月报金额为 3240，运营为 2520，技术仍为 720。检查 Word、PPT、图表标签和说明是否全部更新；再恢复原始值，最终交付回到 3160。</p><p>验收时从一条演示结论出发，应该能找到对应报告段落、汇总公式和原始订单；从一条原始订单出发，也能说明它是否进入本月统计。能完成双向追溯，才说明工作流足够清楚。</p><h2 id="walkthrough" tabindex="-1">图示跟做：让表格、报告和演示使用同一组数字 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：让表格、报告和演示使用同一组数字 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先完成数据材料 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先完成数据材料 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：数据 → 全部刷新。</strong></p><p>从 Sales 八条订单开始，按既定口径刷新查询，等待结束后刷新透视表，核对公式与透视表都是 3160。记录源文件、统计月份和刷新时间，只有这份经过核对的结果才能进入后续 Word 和 PowerPoint。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：再更新文字与图表 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：再更新文字与图表 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 复制。</strong></p><p>从已核对汇总复制结论到 Word，写清日期范围、状态和单位；在 PowerPoint 更新对应图表。需要联动更新时核对链接路径，选择静态图片或数值时记下版本时间。分别检查表格、报告正文和演示标题，防止只更新了图但忘记正文里的旧数字。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：最后生成一次一致的交付包 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：最后生成一次一致的交付包 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：文件 → 导出。</strong></p><p>待 Word 排版、PowerPoint 图表都更新后，分别导出阅读版。随机抽查总额和两个部门金额，要求三份材料一致；把可编辑源文件、阅读版和口径说明放进交付目录。会议后的新意见另记录版本，不直接改已发送文件却保留原版本号。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>图示用 Excel 表示数据起点，后续步骤需要分别切换到 Word 与 PowerPoint。只点一次 Excel 全部刷新，不会保证所有外部文档和演示里的粘贴结果自动更新。</p>',25))])}}});export{g as __pageData,k as default};
